/** Universal completion response. */

import type { ModerationReport } from '../moderation/types';
import type { ContentPart, MediaOutputPart, ToolCallPart } from './messages';

export interface CompletionResponse {
  id: string;
  model: string;
  content: ContentPart[];
  finishReason: FinishReason;
  usage: Usage;

  // Convenience accessors (derived from content[]):
  text: string;
  toolCalls: ToolCallPart[];
  thinking: string | null;

  /** Media output parts (images, audio, video generated by model). */
  media: MediaOutputPart[];

  /** Files produced by hosted tools (e.g. code execution) - charts, data files,
   *  etc. Unified across providers. When only `id` is set, fetch the bytes via the
   *  provider's files API; some providers return `data` inline. Absent when none. */
  files?: FileOutput[];

  /** Hosted (provider-run) builtin tools the model invoked this turn — e.g. a web
   *  search or code-execution run. A durable trail of what was called (the provider
   *  ran them server-side; nothing for the client to execute). Absent when none. */
  builtinToolCalls?: BuiltinToolCall[];

  /** Inline-moderation outcome, when the `moderation` request option was used.
   *  Report-only: present for observability; it never blocks the call. Absent when
   *  moderation was not requested. */
  moderation?: ModerationReport;

  // Timing
  latencyMs: number;

  // Provider's raw response (escape hatch)
  raw: unknown;
}

/** A file produced by a hosted tool (code execution output, etc.). */
export interface FileOutput {
  /** Provider file id, to fetch the bytes separately (e.g. Anthropic container
   *  file_id, OpenAI file_id). */
  id?: string;
  /** Filename, when the provider supplies one. */
  name?: string;
  /** MIME type, when known. */
  mimeType?: string;
  /** Inline bytes (base64) when the provider returns the file inline; else absent. */
  data?: string;
  /** URL to fetch the file when the provider returns one (e.g. OpenAI code-interpreter
   *  image outputs); else absent. */
  url?: string;
  /** What produced it (e.g. 'code_execution'). */
  source?: string;
  /** Provider-specific retrieval hints, used by `retrieveFile`/`streamFile` when the
   *  file is fetched by `id` (e.g. OpenAI container files set `{ containerId }`).
   *  Absent for providers that don't need extra context. */
  ref?: Record<string, unknown>;
}

/** A hosted builtin tool the model invoked (provider-run), with its inputs/outputs. */
export interface BuiltinToolCall {
  /** Unified tool name: `'web_search'` | `'code_interpreter'` | … (normalized from
   *  each provider's native name — e.g. Anthropic `code_execution`). */
  tool: string;
  /** Provider call id, when available (correlates the stream start/end events). */
  id?: string;
  /** `code_interpreter`: the code the model executed. */
  code?: string;
  /** `code_interpreter`: the code's textual output (stdout / logs). */
  output?: string;
  /** `web_search`: the query the model searched for (the first, if it issued several).
   *  Absent for page-open/read steps — see `url`. */
  query?: string;
  /** `web_search`: the URL the model opened/read (OpenAI/xAI `open_page`/`find`
   *  actions, which carry a URL instead of a query). Absent for plain searches. */
  url?: string;
}

export type FinishReason = 'stop' | 'tool_use' | 'length' | 'content_filter' | 'error';

export interface Usage {
  inputTokens: number;
  outputTokens: number;
  totalTokens: number;
  cachedTokens: number;
  cacheWriteTokens: number;
  reasoningTokens: number;
  /** Audio input/output tokens (realtime / audio models). When set, inputTokens/
   *  outputTokens count only the TEXT portion so cost prices each at its own rate. */
  audioInputTokens?: number;
  audioOutputTokens?: number;
  /** Service tier the provider actually billed, RAW as it reported it (openai
   *  `flex|priority|…`, anthropic `standard|priority|batch`). Auditable. */
  serviceTier?: string;
  /** The raw tier normalized by the adapter to the catalog's tier key — what cost
   *  uses for `pricing.tiers[...]`. Set alongside serviceTier; usually identical. */
  pricingTier?: string;
}

export function emptyUsage(): Usage {
  return {
    inputTokens: 0,
    outputTokens: 0,
    totalTokens: 0,
    cachedTokens: 0,
    cacheWriteTokens: 0,
    reasoningTokens: 0,
  };
}
